/* Data-driven review UI; reusable geometry is the existing pure Foundry seam. */
(function () {
  'use strict';
  const D = globalThis.FOUNDRY_MAPS, api = globalThis.FoundryDisplay;
  const $ = s => document.querySelector(s);
  const esc = v => String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const R = new Map(D.resources.map(r => [r.id,r])), A = new Map(D.anchors.map(a=>[a.id,a]));
  const S = new Map(D.sources.map(s=>[s.id,s])), P = new Map(D.process.steps.map(s=>[s.id,s]));
  const N = D.knowledge.nodes, pos = api.seededPositions(N);
  const state = {view:matchMedia('(max-width:760px)').matches?'outline':'disk',focus:null,query:'',category:''};
  function resource(id, label) {return `<a class="button" href="${esc(R.get(id).target)}" data-resource="${id}">${esc(label || R.get(id).title)}</a>`;}
  function anchor(id) {const a=A.get(id);return `<a class="anchor-link" data-source="${id}" href="source-pages/${a.source_id}.html#L${a.start}">${esc(a.source_id)} · ${esc(S.get(a.source_id).kind)} · L${a.start}–${a.end}</a>`;}
  function search() {return D.resources.filter(r=>(!state.category || r.category===state.category) && `${r.title} ${r.summary} ${r.id}`.toLowerCase().includes(state.query.toLowerCase()));}
  function knowledge() {
    let graphic;
    if (state.view==='outline') {
      const branch=id=>'<ul>'+N.filter(n=>n.parent_id===id).map(n=>`<li>${resource(n.resource_id,n.title)}<small>Declared depth ${n.ring} · ${esc(n.facets.join(', '))}</small>${branch(n.id)}</li>`).join('')+'</ul>';
      graphic='<div class="outline">'+branch(null)+'</div>';
    } else {
      const focus=state.focus?pos.get(state.focus):{x:0,y:0};
      const xy=n=>{const p=api.recenter(pos.get(n.id),focus);return {x:300+270*p.x,y:300+270*p.y};};
      graphic='<svg class="disk" viewBox="0 0 600 600" role="group" aria-label="Seeded knowledge disk"><circle class="boundary" cx="300" cy="300" r="280"/>';
      for(const n of N.filter(n=>n.parent_id)){const p=xy(N.find(a=>a.id===n.parent_id)),q=xy(n);graphic+=`<line class="edge" x1="${p.x}" y1="${p.y}" x2="${q.x}" y2="${q.y}"/>`;}
      for(const n of N){const p=xy(n);graphic+=`<a data-node="${n.id}" data-resource="${n.resource_id}" href="${esc(R.get(n.resource_id).target)}" aria-label="Open ${esc(n.title)}"><title>${esc(n.title)}</title><circle cx="${p.x}" cy="${p.y}" r="12" fill="transparent"/><circle class="dot ${n.ring===0?'root-dot':n.ring===1?'domain-dot':''}" cx="${p.x}" cy="${p.y}" r="${n.ring===0?10:n.ring===1?7:5}"/>${n.ring<=1&&!state.focus?`<text x="${p.x}" y="${p.y+23}" text-anchor="middle">${esc(n.ring===0?'A second opinion':n.title)}</text>`:''}</a>`;}
      graphic+='</svg>';
    }
    return `<h2>Knowledge map</h2><p>Follow the branches from purpose to the reading process, scaling, refutation, grading and improvement. Every node opens the actual source-backed Library resource.</p><p class="badge">Seeded geometry · resource access frequency unknown</p>
    <div class="toolbar"><button data-view="disk" aria-pressed="${state.view==='disk'}">Disk</button><button data-view="outline" aria-pressed="${state.view==='outline'}">Outline</button><button data-focus="">Whole map</button></div><div class="map-wrap"><div class="map-board">${graphic}</div><aside class="map-side"><h3>Explore a branch</h3>${N.filter(n=>n.ring===1).map(n=>`<p><button data-focus="${n.id}">${esc(n.title)}</button></p>`).join('')}<p>Positions project a declared parent tree into the disk. They are not learned similarity, measured importance, or use frequency. Use Outline to read every resource name.</p></aside></div>`;
  }
  function library() {const hits=search();return `<h2>Library</h2><p>Repeated needs include source intake, raw drafts, scope control, honest grading and claim checks. Workflow reuse is documented; real resource-access counts remain unknown.</p><div class="toolbar"><label for="library-search">Find a resource</label><input id="library-search" type="search" value="${esc(state.query)}"><select id="category" aria-label="Resource category"><option value="">All categories</option>${[...new Set(D.resources.map(r=>r.category))].map(c=>`<option ${c===state.category?'selected':''}>${esc(c)}</option>`).join('')}</select></div><p>${hits.length} resources</p><div class="card-grid">${hits.map(r=>`<article class="card"><p class="eyebrow">${esc(r.category)}</p><h3>${esc(r.title)}</h3><p>${esc(r.summary)}</p><p class="note">Access frequency unknown</p>${resource(r.id,'Open resource')}</article>`).join('')||'<p>No matching resources.</p>'}</div>`;}
  function process(id) {
    const s=P.get(id)||P.get(D.process.entry),out=D.process.edges.filter(e=>e.source===s.id);
    const groups=['Receive and scope','First program and source analysis','Shard, map and synthesize','Grade or run live refutation','Validate, write and capture','Human review and improvement'];
    return `<h2>Process map</h2><p>Artifact and decision → raw draft or project analysis → deterministic grade or bounded live refutation → qualified advisor output → human use.</p><p class="note">Analyze and live grading are separate branches. Cards distinguish operating instructions, code and model calls. Requested roles do not establish served-model provenance.</p><article class="detail" id="step-detail" data-step-id="${s.id}"><p class="eyebrow">${esc(s.kind)}${s.role?' · '+esc(s.role):''}</p><h2>${esc(s.title)}</h2><p>${esc(s.summary)}</p>${s.fanout?.enabled?`<p><strong>Fan-out:</strong> ${esc(s.swarm)}</p>`:''}<div class="anchor-list">${s.anchors.map(anchor).join('')}</div><div class="actions">${s.resource_ids.map(id=>resource(id)).join(' ')}</div><h3>Next branches</h3><ul class="transitions">${out.map(e=>`<li><a href="#process/${e.target}">${esc(P.get(e.target).title)}</a> — ${esc(e.label)} · ${anchor(e.anchor_id)}</li>`).join('')||'<li>End with the stated qualification.</li>'}</ul></article>${groups.map((title,i)=>`<h3>${i+1}. ${title}</h3><div class="flow">${D.process.steps.filter(s=>s.group===i+1).map(s=>`<a class="step ${s.kind}" data-step="${s.id}" href="#process/${s.id}" ${s.id===id?'aria-current="step"':''}><span class="type">${esc(s.kind)}</span><strong>${esc(s.title)}</strong></a>`).join('')}</div>`).join('')}<p class="note">${P.size} steps and ${D.process.edges.length} source-backed transitions. Select a step to follow the actual branches. No automatic review-to-convergence is claimed.</p>`;
  }
  function differences(){return `<h2>Instructions ↔ code</h2><p>These source-qualified disagreements remain visible. The display changes no engine.</p>${D.process.disagreements.map(d=>`<details class="difference" data-difference="${d.id}"><summary>${esc(d.title)}</summary><p>${esc(d.fact)}</p><div class="anchor-list">${d.anchors.map(anchor).join('')}</div></details>`).join('')}`;}
  function evidence(){return `<h2>Use and improvement</h2><p>Read the recorded outcome before treating a reusable resource as proven practice.</p>${D.observed_examples.map(e=>`<article class="card"><h3>${esc(e.id)}</h3><p>${esc(e.summary)}</p><p class="note">Native subscription receipt not inspected here; original run records and qualifications retained.</p><div class="anchor-list">${e.anchors.map(anchor).join('')}</div></article>`).join('')}<h3>What the records measure</h3><p>${D.usage_audit.records} saved machine records were inspected for explicit resource IDs. None names them. This is an inventory count, not a unique-run count, access frequency, or learned map.</p><p>The saved MIT record reports family/model attestation; paper records contain models:null and conflicting legacy labels. Neither a returned JSON file nor its GROUNDED stamp establishes completed ResearchPrime research verification.</p><h3>Existing improvement pathway</h3><p>A real run's named shortfall → curated usage entry plus machine capture → candidate lesson → formal North-Star and canary checks before any authorized improvement. Construction freeze requires demonstrated current-version use. This draft launches no repair, router, training service or build wave.</p>${resource('improvement')} ${resource('construction-freeze')} ${resource('run-capture')}`;}
  function handoff(){return `<h2>Anchor handoff</h2><p><a href="maps.json">maps.json</a> uses the existing foundry-skill-display/v1 contract. Anchor discovers it under its configured content root at gandalf/maps.json and resolves original sources through its contained reader.</p><p>This review surface also works as a standalone file. Resource pages preserve exact snapshots, source hashes and numbered excerpts. Live Anchor reads the real originals and detects stale anchors.</p><h3>Known integration limits</h3>${D.integration.gaps.map(g=>`<p class="note">${esc(g)}</p>`).join('')}<p>Initial draft for gwl-walk-gandalf. Independent product review remains open; no acceptance or closure is inferred. researchPrime Refinement 1 and original v7 remain available. Aladdin retains stewardship; the Lamp/Tarmac naming decision is separate.</p><p><a href="resources/index.html">Complete Library index</a> · <a href="screenshots/desktop-library.png">Desktop Anchor Library</a> · <a href="screenshots/phone-process.png">Phone Anchor process</a> · <a href="browser-evidence.json">Isolated browser evidence</a></p><p class="note">Isolated rendering and clicks are evidence for this handoff, not activation of John's live Anchor or product acceptance.</p>`;}
  function render(){const [view,id]=location.hash.slice(1).split('/');const current=['knowledge','library','process','differences','evidence','handoff'].includes(view)?view:'knowledge';document.querySelectorAll('[data-tab]').forEach(a=>a.dataset.tab===current?a.setAttribute('aria-current','page'):a.removeAttribute('aria-current'));$('#panel').innerHTML={knowledge,library,process:()=>process(id),differences,evidence,handoff}[current]();}
  function open(target,title){$('#resource-title').textContent=title;$('#resource-frame').src=target;$('#resource-new-tab').href=target;$('#resource-dialog').showModal();}
  document.addEventListener('click',e=>{const r=e.target.closest('[data-resource]');if(r&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();open(R.get(r.dataset.resource).target,R.get(r.dataset.resource).title);return;}const a=e.target.closest('[data-source]');if(a&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey){e.preventDefault();open(a.getAttribute('href'),'Source · '+A.get(a.dataset.source).source_id);return;}const view=e.target.closest('[data-view]');if(view){state.view=view.dataset.view;render();}const focus=e.target.closest('[data-focus]');if(focus){state.focus=focus.dataset.focus||null;state.view='disk';render();}});
  document.addEventListener('input',e=>{if(e.target.id==='library-search'){const caret=e.target.selectionStart;state.query=e.target.value;render();$('#library-search').focus();$('#library-search').setSelectionRange(caret,caret);}});
  document.addEventListener('change',e=>{if(e.target.id==='category'){state.category=e.target.value;render();}});
  $('#close-resource').addEventListener('click',()=>$('#resource-dialog').close());$('#resource-dialog').addEventListener('close',()=>$('#resource-frame').removeAttribute('src'));window.addEventListener('hashchange',()=>{render();if(location.hash.startsWith('#process/'))$('#step-detail').scrollIntoView({block:'start'});});render();
})();
